const normalize = (s) =>
  (s || '')
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();

const idMap = {};
const nameToId = {};
const duplicates = [];

for (const item of $input.all()) {
  let payload = item.json;
  if (Array.isArray(payload)) payload = payload[0];

  const clientes = (payload && payload.clientes) || [];
  for (const c of clientes) {
    if (!c.id) continue;

    idMap[c.id] = {
      nome: c.nome,
      dataCriacao: c.dataCriacao,
    };

    const key = normalize(c.nome);
    if (!key) continue;

    if (nameToId[key] && nameToId[key] !== c.id) {
      duplicates.push({
        level: 'warn',
        message: `Duplicate normalized name "${key}" — kept ${nameToId[key]}, ignored ${c.id} (${c.nome})`,
      });
    } else {
      nameToId[key] = c.id;
    }
  }
}

return [
  {
    json: {
      idMap,
      nameToId,
      duplicates,
      totalClientes: Object.keys(idMap).length,
    },
  },
];

const clientesData = $('Build Clientes Map').first().json;
const { idMap, duplicates } = clientesData;

const supabasePatients = $('Read Supabase Patients').all().map((i) => i.json);

const supabaseIdSet = new Set();
const orphanSupabasePatients = [];

for (const p of supabasePatients) {
  if (!p.id) continue;
  supabaseIdSet.add(p.id);
  if (!idMap[p.id]) {
    orphanSupabasePatients.push({ id: p.id, Nome: p.Nome });
  }
}

const newGestekClients = [];
for (const [id, info] of Object.entries(idMap)) {
  if (!supabaseIdSet.has(id)) {
    newGestekClients.push({
      id,
      nome: info.nome,
      dataCriacao: info.dataCriacao,
    });
  }
}

return [
  {
    json: {
      existingIds: Array.from(supabaseIdSet),
      newGestekClients,
      orphanSupabasePatients,
      duplicates: duplicates || [],
    },
  },
];

